async fn generate(root:&Path,password:&str,groups:usize,dm:usize,group_messages:usize)->Result<(),Error>{
 if root.join("manifest.json").exists(){return Err("fixture already exists; refusing to duplicate accepted messages".into());}
 let owner=Peer::open(&root.join("owner"),password,"Reference owner",true).await?;
 let mut m=Manifest{source:std::env::var("FOUNDATION_SOURCE")?,dm_per_contact:dm,group_messages,..Default::default()};save(root,&m)?;
 let mut outcome=Ok(());
 for group_index in 0..groups {
  let mut peers=Vec::new();
  for index in 0..5 {match Peer::open(&root.join(format!("peer-{:03}",group_index*5+index)),password,"Reference contact",true).await {Ok(peer)=>peers.push(peer),Err(error)=>{outcome=Err(error);break;}}}
  if outcome.is_ok(){match batch(&owner,&peers,group_index,dm,group_messages).await {Ok(group)=>{m.groups.push(*group.as_bytes());m.accounts.extend(peers.iter().map(|p|p.node.account_id()));save(root,&m)?;},Err(error)=>outcome=Err(error)}}
  for peer in peers {if let Err(error)=peer.close().await {outcome=Err(error);}}
  owner.roster.lock().unwrap().evict_stale(Duration::ZERO);
  if outcome.is_err(){break;}
 }
 let closed=owner.close().await;outcome?;closed?;m.completed=true;save(root,&m)?;println!("{}",serde_json::json!({"phase":"generation-complete","groups":m.groups.len(),"contacts":m.accounts.len(),"messages":m.accounts.len()*dm+m.groups.len()*group_messages}));Ok(())
}
