  for (index,id) in m.groups.iter().enumerate(){let start=Instant::now();let rows=owner.node.channel_history(ConversationId::new(*id),50.min(m.group_messages))?;check_rows(&rows,50.min(m.group_messages),&format!("F03 group {index:02} "))?;println!("{}",serde_json::json!({"phase":"group-page","index":index,"rows":rows.len(),"elapsed_us":start.elapsed().as_micros()}));}
  Ok(())
 })();let closed=owner.close().await;outcome?;closed?;Ok(())
}
