+//! Continue durable incoming DM work independently of further network traffic.
+use super::*;
+
+#[derive(Default)]
+struct ReceiveSweep {
+    after: Option<ConversationId>,
+    progressed: bool,
+    resweep: bool,
+}
+
+enum ReceiveTurn {
+    Continue,
+    Blocked,
+    Settled,
+}
+
+impl Node {
+    fn receive_projection_turn(&self, sweep: &mut ReceiveSweep) -> Result<ReceiveTurn, NodeError> {
+        let repository = self.log.lock().expect("log lock").repository()?.clone();
+        // Metadata discovery and payload projection retain their existing separate
+        // 128-row budgets. Never materialize all conversation keys or bodies.
+        let discovering = repository.discover_receives()?;
+        if let Some(conversation) = repository.pending_receive_conversation(sweep.after)? {
+            sweep.after = Some(conversation);
+            match self.project_dm_receive_page(conversation) {
+                Ok(count) => sweep.progressed |= count > 0,
+                Err(error) => {
+                    // One blocked conversation must not suppress the next lane.
+                    log::warn!("DM receive projection deferred: {error}");
+                }
+            }
+            return Ok(ReceiveTurn::Continue);
+        }
+        let pending = repository.pending_receive_conversation(None)?.is_some();
+        let again = discovering || sweep.resweep || (pending && sweep.progressed);
+        *sweep = ReceiveSweep::default();
+        Ok(if again {
+            ReceiveTurn::Continue
+        } else if pending {
+            ReceiveTurn::Blocked
+        } else {
+            ReceiveTurn::Settled
+        })
+    }
+
+    pub(super) async fn run_receive_projection_loop(self: Arc<Self>) {
+        let mut maintenance = self.storage.database().subscribe_maintenance_changes();
+        let mut deadline = Some(tokio::time::Instant::now());
+        let mut sweep = ReceiveSweep::default();
+        loop {
+            tokio::select! {
+                _ = async {
+                    match deadline {
+                        Some(at) => tokio::time::sleep_until(at).await,
+                        None => std::future::pending::<()>().await,
+                    }
+                } => {},
+                _ = self.receive_projection_notify.notified() => sweep.resweep = true,
+                changed = maintenance.changed() => {
+                    if changed.is_err() { return; }
+                    sweep.resweep = true;
+                },
+            }
+            // Acknowledge before admission: concurrent policy changes must keep
+            // their following turn. Queue bookkeeping does not wake this owner.
+            let _ = *maintenance.borrow_and_update();
+            let Some(capacity) = self.runtime_work.local_repair_capacity().await else {
+                return;
+            };
+            let Some(work) = self.runtime_work.admit() else {
+                return;
+            };
+            let node = self.clone();
+            let result = work
+                .spawn_local_repair_blocking(capacity, move || {
+                    let result = node.receive_projection_turn(&mut sweep);
+                    (sweep, result)
+                })
+                .await
+                .map(|value| value.into_inner());
+            let outcome = match result {
+                Ok((next, Ok(outcome))) => {
+                    sweep = next;
+                    outcome
+                }
+                Ok((next, Err(error))) => {
+                    sweep = next;
+                    log::warn!("DM receive queue recovery deferred: {error}");
+                    ReceiveTurn::Blocked
+                }
+                Err(error) => {
+                    sweep = ReceiveSweep::default();
+                    log::warn!("DM receive worker failed: {error}");
+                    ReceiveTurn::Blocked
+                }
+            };
+            deadline = match outcome {
+                ReceiveTurn::Continue => Some(tokio::time::Instant::now()),
+                ReceiveTurn::Blocked => Some(
+                    tokio::time::Instant::now() + Duration::from_secs(300),
+                ),
+                ReceiveTurn::Settled => None,
+            };
+            tokio::task::yield_now().await;
+        }
+    }
