fn receive_projection_cut_is_finite_and_excludes_later_arrivals() {
    let dir = tempfile::tempdir().unwrap();
    let (_profile, repo, local, account) = receive_profile(&dir);
    let peer = DeviceIdentity::generate();
    let mut expected = std::collections::HashSet::new();
    let mut conversation = None;
    for sequence in 1..=257 {
        let item = event(&peer, sequence, vec![], sequence, EventKind::Message);
        conversation = Some(item.conversation_id);
        expected.insert(item.id);
        repo.append(&item).unwrap();
