    assert_eq!(first.len(), 128);
    assert!(more);
    let late = event(&peer, 258, vec![], 258, EventKind::Message);
    repo.append(&late).unwrap();
    let (second, more) = repo.pending_receive_page_before(conversation, upper).unwrap();
